CREATE TABLE instances(instance_uid TEXT PRIMARY KEY,source_type TEXT NOT NULL CHECK(source_type IN ('codebeamer','polarion')),base_url TEXT NOT NULL,display_name TEXT NOT NULL,auth_ref TEXT NOT NULL,api_profile TEXT,tls_ca_ref TEXT,supports_discovery INTEGER NOT NULL DEFAULT 0,capability_probe_at TEXT,UNIQUE(source_type,base_url));
CREATE TABLE projects(project_uid TEXT PRIMARY KEY,instance_uid TEXT NOT NULL REFERENCES instances,source_project_id TEXT NOT NULL,name TEXT NOT NULL,url TEXT,selection_policy TEXT,active_generation_uid TEXT REFERENCES index_generations,UNIQUE(instance_uid,source_project_id));
CREATE TABLE project_selections(project_uid TEXT PRIMARY KEY REFERENCES projects,selection_mode TEXT NOT NULL CHECK(selection_mode IN ('ALL','SELECTED')),scope_kind TEXT NOT NULL CHECK(scope_kind IN ('TRACKER','WORK_ITEM_TYPE')),scope_ids TEXT NOT NULL,config_revision INTEGER NOT NULL,preflight_status TEXT,scope_snapshot_hash TEXT);
CREATE TRIGGER selection_kind_insert BEFORE INSERT ON project_selections WHEN NEW.scope_kind != (SELECT CASE source_type WHEN 'codebeamer' THEN 'TRACKER' ELSE 'WORK_ITEM_TYPE' END FROM instances JOIN projects USING(instance_uid) WHERE project_uid=NEW.project_uid) BEGIN SELECT RAISE(ABORT,'source scope mismatch'); END;
CREATE TRIGGER selection_kind_update BEFORE UPDATE ON project_selections WHEN NEW.scope_kind != (SELECT CASE source_type WHEN 'codebeamer' THEN 'TRACKER' ELSE 'WORK_ITEM_TYPE' END FROM instances JOIN projects USING(instance_uid) WHERE project_uid=NEW.project_uid) BEGIN SELECT RAISE(ABORT,'source scope mismatch'); END;
CREATE TABLE containers(container_uid TEXT PRIMARY KEY,project_uid TEXT NOT NULL REFERENCES projects,source_kind TEXT NOT NULL CHECK(source_kind IN ('tracker','workitem_type')),source_container_id TEXT NOT NULL,name TEXT NOT NULL,UNIQUE(project_uid,source_kind,source_container_id));
CREATE TABLE items(item_uid TEXT PRIMARY KEY,project_uid TEXT NOT NULL REFERENCES projects,source_item_id TEXT NOT NULL,type TEXT,status TEXT,deleted_state TEXT NOT NULL DEFAULT 'active' CHECK(deleted_state IN ('active','deleted','missing','unauthorized')),active_revision_uid TEXT,UNIQUE(project_uid,source_item_id),FOREIGN KEY(active_revision_uid,item_uid) REFERENCES item_revisions(revision_uid,item_uid));
CREATE TABLE item_revisions(revision_uid TEXT PRIMARY KEY,item_uid TEXT NOT NULL REFERENCES items,source_revision TEXT NOT NULL,captured_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,modified_at TEXT,raw_payload TEXT NOT NULL,hash TEXT NOT NULL,UNIQUE(item_uid,source_revision),UNIQUE(revision_uid,item_uid));
CREATE TRIGGER immutable_revision_update BEFORE UPDATE ON item_revisions BEGIN SELECT RAISE(ABORT,'immutable revision'); END;
CREATE TRIGGER immutable_revision_delete BEFORE DELETE ON item_revisions BEGIN SELECT RAISE(ABORT,'immutable revision'); END;
CREATE TABLE field_definitions(field_def_uid TEXT PRIMARY KEY,instance_uid TEXT NOT NULL REFERENCES instances,scope TEXT NOT NULL,source_field_id TEXT NOT NULL,kind TEXT,data_type TEXT,embed_policy TEXT,UNIQUE(instance_uid,scope,source_field_id));
CREATE TABLE field_values(revision_uid TEXT NOT NULL REFERENCES item_revisions,field_def_uid TEXT NOT NULL REFERENCES field_definitions,raw_value TEXT,normalized_value TEXT,source_format TEXT,PRIMARY KEY(revision_uid,field_def_uid));
CREATE TABLE content_blocks(block_uid TEXT NOT NULL,revision_uid TEXT NOT NULL REFERENCES item_revisions,field_def_uid TEXT REFERENCES field_definitions,block_order INTEGER NOT NULL,type TEXT NOT NULL CHECK(type IN ('text','table')),raw_html TEXT,table_json TEXT,normalized_text TEXT,PRIMARY KEY(revision_uid,block_uid));
CREATE TABLE attachments(attachment_uid TEXT PRIMARY KEY,item_uid TEXT NOT NULL,revision_uid TEXT NOT NULL,source_url TEXT,filename TEXT,checksum TEXT,disk_path TEXT,download_status TEXT,FOREIGN KEY(revision_uid,item_uid) REFERENCES item_revisions(revision_uid,item_uid));
CREATE TABLE relations(relation_uid TEXT PRIMARY KEY,revision_uid TEXT NOT NULL REFERENCES item_revisions,original_relation_type TEXT NOT NULL,source_target_id TEXT NOT NULL,target_uid TEXT REFERENCES items);
CREATE TABLE chunks(chunk_uid TEXT PRIMARY KEY,revision_uid TEXT NOT NULL REFERENCES item_revisions,field_def_uid TEXT REFERENCES field_definitions,block_uid TEXT,chunk_key TEXT NOT NULL,input_text TEXT NOT NULL,content_hash TEXT NOT NULL,model_fingerprint TEXT NOT NULL,input_tokens INTEGER NOT NULL CHECK(input_tokens>=0),source_span_offsets TEXT,row_ids TEXT,embedding_input_digest TEXT NOT NULL,tokenizer_id TEXT NOT NULL,effective_max_input_tokens INTEGER NOT NULL CHECK(effective_max_input_tokens>0),truncation_detected INTEGER NOT NULL DEFAULT 0 CHECK(truncation_detected=0),CHECK(input_tokens<=effective_max_input_tokens),UNIQUE(revision_uid,chunk_key,model_fingerprint),FOREIGN KEY(revision_uid,block_uid) REFERENCES content_blocks(revision_uid,block_uid));
CREATE TABLE index_generations(generation_uid TEXT PRIMARY KEY,project_uid TEXT NOT NULL REFERENCES projects,model_config TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'PREPARED' CHECK(state IN ('PREPARED','VALIDATED','RETIRED','FAILED')),validation_evidence TEXT,activated_at TEXT,CHECK(state!='VALIDATED' OR (validation_evidence IS NOT NULL AND length(validation_evidence)>0)));
CREATE TRIGGER generation_activate_insert BEFORE INSERT ON projects WHEN NEW.active_generation_uid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM index_generations WHERE generation_uid=NEW.active_generation_uid AND project_uid=NEW.project_uid AND state='VALIDATED') BEGIN SELECT RAISE(ABORT,'invalid generation'); END;
CREATE TRIGGER generation_activate_update BEFORE UPDATE ON projects WHEN NEW.active_generation_uid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM index_generations WHERE generation_uid=NEW.active_generation_uid AND project_uid=NEW.project_uid AND state='VALIDATED') BEGIN SELECT RAISE(ABORT,'invalid generation'); END;
CREATE TRIGGER generation_preserve BEFORE UPDATE ON index_generations WHEN EXISTS(SELECT 1 FROM projects WHERE active_generation_uid=OLD.generation_uid) AND (NEW.state!='VALIDATED' OR NEW.project_uid!=OLD.project_uid OR NEW.generation_uid!=OLD.generation_uid) BEGIN SELECT RAISE(ABORT,'active generation immutable ownership'); END;
CREATE TABLE index_points(point_uuid TEXT PRIMARY KEY,generation_uid TEXT NOT NULL REFERENCES index_generations,chunk_uid TEXT NOT NULL REFERENCES chunks,vector_status TEXT NOT NULL CHECK(vector_status IN ('PREPARED','READY','RETIRED')),source_hash TEXT NOT NULL,UNIQUE(generation_uid,chunk_uid));
CREATE TRIGGER point_ownership BEFORE INSERT ON index_points WHEN (SELECT project_uid FROM index_generations WHERE generation_uid=NEW.generation_uid)!=(SELECT i.project_uid FROM chunks c JOIN item_revisions r USING(revision_uid) JOIN items i USING(item_uid) WHERE c.chunk_uid=NEW.chunk_uid) BEGIN SELECT RAISE(ABORT,'point project mismatch'); END;
CREATE TABLE rate_limit_policies(instance_uid TEXT NOT NULL REFERENCES instances,credential_scope TEXT NOT NULL,rps REAL NOT NULL CHECK(rps>0),burst INTEGER NOT NULL CHECK(burst>0),max_inflight INTEGER NOT NULL CHECK(max_inflight>0),min_interval REAL NOT NULL DEFAULT 0,PRIMARY KEY(instance_uid,credential_scope));
CREATE TABLE rate_limit_states(instance_uid TEXT NOT NULL,credential_scope TEXT NOT NULL,next_eligible_at REAL NOT NULL DEFAULT 0,pause_until REAL NOT NULL DEFAULT 0,circuit_state TEXT NOT NULL DEFAULT 'CLOSED',PRIMARY KEY(instance_uid,credential_scope),FOREIGN KEY(instance_uid,credential_scope) REFERENCES rate_limit_policies);
CREATE TABLE jobs(sequence INTEGER PRIMARY KEY AUTOINCREMENT,job_id TEXT NOT NULL UNIQUE,project_uid TEXT NOT NULL REFERENCES projects,stage TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'QUEUED' CHECK(state IN ('QUEUED','RUNNING','SUCCEEDED','COMPLETED_WITH_ERRORS','PAUSED','BLOCKED','FAILED','CANCELLED')),checkpoint TEXT NOT NULL DEFAULT '{}',owner TEXT,fencing_token TEXT,lease_expires_at REAL,retry_count INTEGER NOT NULL DEFAULT 0,created_at REAL NOT NULL,updated_at REAL NOT NULL,last_error_code TEXT,progress_total INTEGER NOT NULL DEFAULT 0,succeeded_items INTEGER NOT NULL DEFAULT 0,failed_items INTEGER NOT NULL DEFAULT 0,skipped_items INTEGER NOT NULL DEFAULT 0,CHECK(progress_total>=succeeded_items+failed_items+skipped_items),CHECK(succeeded_items>=0 AND failed_items>=0 AND skipped_items>=0));
CREATE UNIQUE INDEX one_running_job ON jobs(state) WHERE state='RUNNING';
CREATE TABLE job_steps(step_uid TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES jobs(job_id),stage TEXT NOT NULL,state TEXT NOT NULL,checkpoint TEXT NOT NULL DEFAULT '{}',retry_count INTEGER NOT NULL DEFAULT 0,error_code TEXT);
CREATE TABLE job_events(event_id INTEGER PRIMARY KEY AUTOINCREMENT,job_id TEXT NOT NULL REFERENCES jobs(job_id),occurred_at REAL NOT NULL,state TEXT NOT NULL,error_code TEXT);
CREATE TABLE failed_items(failed_item_uid TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES jobs(job_id),project_uid TEXT NOT NULL REFERENCES projects,item_uid TEXT NOT NULL REFERENCES items,revision_uid TEXT NOT NULL REFERENCES item_revisions,failed_stage TEXT NOT NULL,error_class TEXT NOT NULL,retryable INTEGER NOT NULL CHECK(retryable IN (0,1)),attempts INTEGER NOT NULL DEFAULT 1,trace_id TEXT,replay_state TEXT NOT NULL DEFAULT 'PENDING',UNIQUE(job_id,item_uid,failed_stage,revision_uid));
CREATE TABLE job_item_attempts(attempt_uid TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES jobs(job_id),item_uid TEXT NOT NULL REFERENCES items,revision_uid TEXT REFERENCES item_revisions,stage TEXT NOT NULL,state TEXT NOT NULL,error_class TEXT,trace_id TEXT);
CREATE TABLE api_principals(key_uid TEXT PRIMARY KEY,key_hash TEXT NOT NULL UNIQUE,role TEXT NOT NULL,revoked_at TEXT);
CREATE TABLE principal_project_grants(key_uid TEXT NOT NULL REFERENCES api_principals,project_uid TEXT NOT NULL REFERENCES projects,method_scope TEXT NOT NULL,PRIMARY KEY(key_uid,project_uid,method_scope));
CREATE TABLE audit_entries(audit_uid TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,target TEXT,occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,outcome TEXT NOT NULL);
CREATE TRIGGER failed_item_owner_insert BEFORE INSERT ON failed_items WHEN NOT EXISTS(SELECT 1 FROM jobs j JOIN items i ON i.project_uid=j.project_uid JOIN item_revisions r ON r.item_uid=i.item_uid WHERE j.job_id=NEW.job_id AND j.project_uid=NEW.project_uid AND i.item_uid=NEW.item_uid AND r.revision_uid=NEW.revision_uid) BEGIN SELECT RAISE(ABORT,'failure ownership mismatch'); END;
CREATE TRIGGER failed_item_owner_update BEFORE UPDATE ON failed_items WHEN NOT EXISTS(SELECT 1 FROM jobs j JOIN items i ON i.project_uid=j.project_uid JOIN item_revisions r ON r.item_uid=i.item_uid WHERE j.job_id=NEW.job_id AND j.project_uid=NEW.project_uid AND i.item_uid=NEW.item_uid AND r.revision_uid=NEW.revision_uid) BEGIN SELECT RAISE(ABORT,'failure ownership mismatch'); END;
CREATE TRIGGER point_ownership_update BEFORE UPDATE ON index_points WHEN (SELECT project_uid FROM index_generations WHERE generation_uid=NEW.generation_uid)!=(SELECT i.project_uid FROM chunks c JOIN item_revisions r USING(revision_uid) JOIN items i USING(item_uid) WHERE c.chunk_uid=NEW.chunk_uid) BEGIN SELECT RAISE(ABORT,'point project mismatch'); END;
CREATE TABLE chunk_budgets(project_uid TEXT PRIMARY KEY REFERENCES projects,target_tokens INTEGER NOT NULL DEFAULT 512,max_tokens INTEGER NOT NULL DEFAULT 1024,overlap_tokens INTEGER NOT NULL DEFAULT 64,context_budget INTEGER NOT NULL DEFAULT 1024,CHECK(target_tokens>0 AND max_tokens>=target_tokens AND overlap_tokens>=0 AND overlap_tokens<target_tokens AND context_budget>=max_tokens));
